    );
  });

  it("POSTs pathless recording blobs", async () => {
    const spy = vi.fn(() =>
      Promise.resolve(
        new Response(JSON.stringify({ path: "C:/tmp/staged-2-r.wav" })),
      ),
    );
    vi.stubGlobal("fetch", spy);
    const a = audio({
