/**
 * stageAudioForEngine (#86) — hand browser-held audio bytes to the dev
 * engine bridge so `kind:"file"` drops and pathless recordings can drive
 * a real transcription job.
 *
 * Refs that already live on disk (`kind:"path"`, recordings persisted by
 * the Tauri capture) need no staging — buildTranscriptionParams picks
 * their path up directly. Only in-browser bytes are POSTed to
 * `/__engine/stage`, which writes them under %TEMP%/hornscribe-dev and
 * returns a real path for `job.start`.
 *
 * Returns null when there is nothing to stage or the bridge is not
 * reachable (mock engine dev sessions keep working — the mock ignores
 * params anyway).
 */

import type { AudioFileRef, LoadedAudio, RecordedAudioRef } from "./types";

function bytesOf(ref: AudioFileRef | RecordedAudioRef): Blob | null {
  if (ref.kind === "file") return ref.file;
  if (ref.kind === "recording" && !ref.path && ref.blob) return ref.blob;
  return null; // kind === "path", or a recording already on disk
}

export async function stageAudioForEngine(
  audio: LoadedAudio | null,
): Promise<string | null> {
  if (!audio) return null;
  const bytes = bytesOf(audio.ref);
  if (!bytes) return null;
  try {
    const res = await fetch(
      "/__engine/stage?name=" + encodeURIComponent(audio.fileName),
      { method: "POST", body: bytes },
    );
    if (!res.ok) return null;
    const body = (await res.json()) as { path?: unknown };
    return typeof body.path === "string" ? body.path : null;
  } catch {
    return null;
  }
}

/**
 * Build the `job.start` params for the real `transcription` job kind
 * (ENG-002) from the loaded audio + the 採譜オプション popover state.
 *
 * Wire contract (python/hornscribe/transcription/options.py):
 * `audioPath` is required — the engine reads the file itself, so only
 * refs backed by a real path can drive a real job:
 *
 * - `kind:"path"` (native dialog / native drop) -> the path itself;
 * - `kind:"recording"` with `path` (Tauri capture: the WAV was already
 *   persisted under appDataDir/recordings/) -> that path;
 * - `kind:"file"` (browser dev drop) and pathless recordings -> staged
 *   first via stageAudioForEngine (#86): the dev bridge writes the bytes
 *   under %TEMP%/hornscribe-dev and the returned path is passed in as
 *   `stagedAudioPath`, which wins over every ref-derived path. When the
 *   bridge is unreachable staging returns null and the mock engine
 *   ignores params anyway, so dev sessions still exercise the flow.
 *
 * `tempoBpm` is only sent for manual tempo — auto omits it so the
 * engine runs beat tracking. `range:"selection"` sends the user's
 * start/end seconds, clamped to the clip duration.
 */
import type {
  AudioFileRef,
  LoadedAudio,
  RecordedAudioRef,
  TranscriptionOptions,
} from "./types";

function audioPathOf(ref: AudioFileRef | RecordedAudioRef): string | null {
  if (ref.kind === "path") return ref.path;
  if (ref.kind === "recording") return ref.path ?? null;
  return null; // kind === "file": browser dev, no on-disk source
}

export interface TranscriptionJobParams {
  audioPath?: string;
  tempoBpm?: number;
  meter?: string;
  minDuration?: string;
  triplets?: string;
  simplicity?: string;
  range?: string;
  selectionStartSec?: number;
  selectionEndSec?: number;
}

export function buildTranscriptionParams(
  audio: LoadedAudio | null,
  options: TranscriptionOptions,
  stagedAudioPath: string | null = null,
): TranscriptionJobParams {
  const params: TranscriptionJobParams = {};
  const path = stagedAudioPath ?? (audio ? audioPathOf(audio.ref) : null);
  if (path) params.audioPath = path;

  if (options.tempo === "manual" && options.tempoBpm != null) {
    params.tempoBpm = options.tempoBpm;
  }
  // "auto" meter is the engine default; only pin an explicit choice.
  if (options.meter && options.meter !== "auto") {
    params.meter = options.meter;
  }
  if (options.minDuration) params.minDuration = options.minDuration;
  if (options.triplets !== "auto") params.triplets = options.triplets;
  if (options.simplicity !== "standard") {
    params.simplicity = options.simplicity;
  }
  if (options.range === "selection") {
    params.range = "selection";
    // The engine requires end > start for selection mode; clamp the
    // user's seconds into [0, duration] and fall back to the full span
    // when the pair is empty or inverted.
    const dur = audio?.durationSeconds ?? 0;
    let start = options.selectionStartSec ?? 0;
    let end = options.selectionEndSec ?? dur;
    start = Math.min(Math.max(start, 0), dur);
    end = Math.min(Math.max(end, 0), dur);
    if (end <= start) {
      start = 0;
      end = dur;
    }
    params.selectionStartSec = start;
    params.selectionEndSec = end;
  }
  return params;
}

/**
 * DevBridgeSidecarPort tests (#86): the browser-dev transport must
 * (a) fall back to the in-process mock when the Vite bridge is absent,
 * (b) relay spawn/write/SSE faithfully when the bridge is up.
 * fetch and EventSource are stubbed — jsdom has no EventSource.
 */

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { DevBridgeSidecarPort } from "./devBridgePort";
import { SidecarError } from "./protocol";

class FakeEventSource {
  static instances: FakeEventSource[] = [];
  onmessage: ((ev: { data: string }) => void) | null = null;
  closed = false;
  constructor(public readonly url: string) {
    FakeEventSource.instances.push(this);
  }
  emit(obj: unknown): void {
    this.onmessage?.({ data: JSON.stringify(obj) });
  }
  close(): void {
    this.closed = true;
  }
}

function jsonResponse(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json" },
  });
}

describe("DevBridgeSidecarPort", () => {
  const realFetch = globalThis.fetch;
  const realES = globalThis.EventSource;

  beforeEach(() => {
    FakeEventSource.instances = [];
    vi.stubGlobal("EventSource", FakeEventSource);
  });
  afterEach(() => {
    vi.stubGlobal("fetch", realFetch);
    vi.stubGlobal("EventSource", realES);
  });

  it("falls back to the mock engine when the bridge is unreachable", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn(() => Promise.reject(new Error("connection refused"))),
    );
    const port = new DevBridgeSidecarPort();
    const lines: string[] = [];
    const exits: Array<number | null> = [];
    port.onLine((l) => lines.push(l));
    port.onExit((c) => exits.push(c));

    await port.start();

    // The mock speaks the real NDJSON contract — a handshake request
    // produces a response line without any bridge involvement.
    port.writeLine(
      JSON.stringify({
        v: 1,
        kind: "request",
        id: "r1",
        method: "engine.ping",
        payload: { echo: "hi" },
      }),
    );
    expect(lines.some((l) => l.includes('"engine.ping"'))).toBe(true);

    port.closeStdin(); // mock: EOF -> exit 0
    expect(exits).toEqual([0]);
  });

  it("spawns through the bridge and relays SSE events", async () => {
    const calls: Array<{ url: string; init?: RequestInit }> = [];
    vi.stubGlobal(
      "fetch",
      vi.fn((url: string, init?: RequestInit) => {
        calls.push({ url, init });
        if (url === "/__engine/health") {
          return Promise.resolve(jsonResponse(200, { ok: true, python: "py" }));
        }
        if (url === "/__engine/spawn") {
          return Promise.resolve(jsonResponse(200, { ok: true }));
        }
        return Promise.resolve(jsonResponse(200, { ok: true }));
      }),
    );
    const port = new DevBridgeSidecarPort();
    const lines: string[] = [];
    const stderrs: string[] = [];
    const exits: Array<number | null> = [];
    port.onLine((l) => lines.push(l));
    port.onStderr((l) => stderrs.push(l));
    port.onExit((c) => exits.push(c));

    await port.start();

    // SSE stream opened before the spawn POST (no lost early output).
    expect(FakeEventSource.instances).toHaveLength(1);
    expect(calls.map((c) => c.url)).toEqual([
      "/__engine/health",
      "/__engine/spawn",
    ]);

    const es = FakeEventSource.instances[0];
    es.emit({ kind: "line", line: '{"v":1}' });
    es.emit({ kind: "stderr", line: "INFO worker" });
    expect(lines).toEqual(['{"v":1}']);
    expect(stderrs).toEqual(["INFO worker"]);

    port.writeLine('{"v":1,"kind":"request"}');
    const write = calls.find((c) => c.url === "/__engine/write");
    expect(write?.init?.method).toBe("POST");
    expect(JSON.parse(String(write?.init?.body))).toEqual({
      line: '{"v":1,"kind":"request"}',
    });

    es.emit({ kind: "exit", code: 0 });
    es.emit({ kind: "exit", code: 0 });
    expect(exits).toEqual([0]); // fires exactly once
    expect(es.closed).toBe(true);
  });

  it("rejects start() with ENGINE_UNAVAILABLE when spawn fails", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn((url: string) =>
        url === "/__engine/health"
          ? Promise.resolve(jsonResponse(200, { ok: true }))
          : Promise.resolve(jsonResponse(500, { error: "no python" })),
      ),
    );
    const port = new DevBridgeSidecarPort();
    await expect(port.start()).rejects.toBeInstanceOf(SidecarError);
    // The SSE stream is cleaned up when spawn fails.
    expect(FakeEventSource.instances[0].closed).toBe(true);
  });
});

/**
 * DevBridgeSidecarPort — the browser-dev {@link SidecarPort} (#86).
 *
 * Inside the Tauri webview the worker is spawned by Rust (engine.rs). In a
 * plain browser there is no process API, so `vite dev` used to fall back to
 * MockSidecarPort and `kind:"file"` audio could never reach the real
 * engine. The devEngineBridge Vite middleware (scripts/devEngineBridge.mjs)
 * exposes the same lifecycle over localhost HTTP + SSE on the dev origin,
 * so this port mirrors {@link TauriSidecarPort} one-for-one:
 *
 *   start()      -> GET /__engine/health (probe) then POST /__engine/spawn
 *   writeLine()  -> POST /__engine/write {line}
 *   closeStdin() -> POST /__engine/stdin-close
 *   kill()       -> POST /__engine/kill
 *   events       -> GET /__engine/events SSE {kind:line|stderr|exit}
 *
 * When the bridge is unreachable (production build opened in a browser,
 * or a dev server without the plugin) start() falls back to an in-process
 * {@link MockSidecarPort} and relays its events — dev sessions keep
 * working exactly as before instead of dead-ending on ENGINE_UNAVAILABLE.
 */

import { ERR, SidecarError } from "./protocol";
import { MockSidecarPort } from "./mockPort";
import type { SidecarPort } from "./port";

const HEALTH_TIMEOUT_MS = 1500;

interface DevBridgeEvent {
  kind: "line" | "stderr" | "exit";
  line?: string;
  code?: number | null;
}

export class DevBridgeSidecarPort implements SidecarPort {
  private readonly lineCbs = new Set<(line: string) => void>();
  private readonly stderrCbs = new Set<(line: string) => void>();
  private readonly exitCbs = new Set<(code: number | null) => void>();
  private fallback: MockSidecarPort | null = null;
  private events: EventSource | null = null;
  private exitFired = false;
  private running = false;

  async start(): Promise<void> {
    if (!(await this.bridgeUp())) {
      // No bridge (e.g. `vite preview` in a browser): behave exactly like
      // the old default — a mock engine that still exercises the UX.
      const mock = new MockSidecarPort();
      this.fallback = mock;
      mock.onLine((l) => {
        for (const cb of [...this.lineCbs]) cb(l);
      });
      mock.onStderr((l) => {
        for (const cb of [...this.stderrCbs]) cb(l);
      });
      mock.onExit((c) => this.fireExit(c));
      await mock.start();
      this.running = true;
      return;
    }

    // Subscribe to the SSE stream before spawning so no early worker
    // output (handshake line) can be lost between the two requests.
    const events = new EventSource("/__engine/events");
    this.events = events;
    events.onmessage = (ev) => {
      let msg: DevBridgeEvent;
      try {
        msg = JSON.parse(ev.data) as DevBridgeEvent;
      } catch {
        return;
      }
      switch (msg.kind) {
        case "line":
          if (typeof msg.line === "string") {
            for (const cb of [...this.lineCbs]) cb(msg.line);
          }
          break;
        case "stderr":
          if (typeof msg.line === "string") {
            for (const cb of [...this.stderrCbs]) cb(msg.line);
          }
          break;
        case "exit":
          this.fireExit(msg.code ?? null);
          break;
      }
    };

    try {
      const res = await fetch("/__engine/spawn", { method: "POST" });
      if (!res.ok) {
        const body = (await res.json().catch(() => null)) as {
          error?: string;
        } | null;
        throw new Error(body?.error ?? `spawn failed (${res.status})`);
      }
    } catch (e) {
      events.close();
      this.events = null;
      throw new SidecarError(
        ERR.ENGINE_UNAVAILABLE,
        e instanceof Error ? e.message : String(e),
      );
    }
    this.running = true;
  }

  writeLine(line: string): void {
    if (!this.running) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "engine is not running");
    }
    if (this.fallback) {
      this.fallback.writeLine(line);
      return;
    }
    void fetch("/__engine/write", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ line }),
    }).catch(() => {
      /* a write into a dead worker is reported by the exit event */
    });
  }

  closeStdin(): void {
    if (!this.running) return;
    if (this.fallback) {
      this.fallback.closeStdin();
      return;
    }
    void fetch("/__engine/stdin-close", { method: "POST" }).catch(
      () => undefined,
    );
  }

  kill(): void {
    if (!this.running) return;
    if (this.fallback) {
      this.fallback.kill();
      return;
    }
    void fetch("/__engine/kill", { method: "POST" }).catch(() => undefined);
  }

  onLine(cb: (line: string) => void): () => void {
    this.lineCbs.add(cb);
    return () => this.lineCbs.delete(cb);
  }
  onStderr(cb: (line: string) => void): () => void {
    this.stderrCbs.add(cb);
    return () => this.stderrCbs.delete(cb);
  }
  onExit(cb: (code: number | null) => void): () => void {
    this.exitCbs.add(cb);
    return () => this.exitCbs.delete(cb);
  }

  private async bridgeUp(): Promise<boolean> {
    try {
      const res = await fetch("/__engine/health", {
        signal: AbortSignal.timeout(HEALTH_TIMEOUT_MS),
      });
      if (!res.ok) return false;
      const body = (await res.json()) as { ok?: boolean; python?: unknown };
      // ok without a resolvable Python is still "up" — spawn will report
      // the honest error, which beats silently mocking a real engine.
      return body.ok === true;
    } catch {
      return false;
    }
  }

  private fireExit(code: number | null): void {
    if (this.exitFired) return; // contract: fires exactly once
    this.exitFired = true;
    this.running = false;
    this.events?.close();
    this.events = null;
    for (const cb of [...this.exitCbs]) cb(code);
  }
}

/**
 * SidecarPort — the transport seam between the typed NDJSON client and a
 * concrete worker process.
 *
 * The port owns process lifecycle only: it delivers whole stdout lines to
 * the client and accepts whole request lines back. It knows nothing about
 * the protocol (no JSON parsing) — that layering mirrors the UI-002 test
 * harness (`WorkerHandle`), which is why the same client runs against the
 * in-process MockSidecarPort and, later, a Tauri-spawned worker unchanged.
 *
 * ## Packaged-app transport (ENG-002)
 *
 * Inside the Tauri webview the worker is spawned by the shell's own
 * `engine` module (src-tauri/src/engine.rs): `engine_spawn` launches
 * `python -m hornscribe.worker` and relays stdout/stderr/exit over a
 * `Channel` — see {@link TauriSidecarPort}. No plugin capability was
 * widened: app-defined commands are not ACL-gated and the spawned
 * program is fixed Rust-side, so the bridge cannot be turned into a
 * general process launcher. `UnsupportedSidecarPort` remains the
 * explicit-failure placeholder for runtimes with no spawn bridge.
 */

import { ERR, SidecarError } from "./protocol";
import { DevBridgeSidecarPort } from "./devBridgePort";
import { TauriSidecarPort } from "./tauriPort";
import { isTauriRuntime } from "../tauri/bridge";

export interface SidecarPort {
  /**
   * Spawn/attach the worker. Resolves when the process is up and its
   * stdin is writable — the protocol handshake happens after this, on the
   * client. Rejects when the worker cannot be launched at all.
   */
  start(): Promise<void>;
  /** Write one NDJSON frame to the worker's stdin (a newline is appended). */
  writeLine(line: string): void;
  /**
   * Close the worker's stdin — the worker treats EOF as an implicit
   * graceful `engine.shutdown` (worker.py contract).
   */
  closeStdin(): void;
  /**
   * Terminate the worker immediately. This is the documented
   * terminate/restart fallback for non-interruptible jobs and the
   * unresponsive-worker path (ENGINE_RUNTIME_MATRIX / ADR-0002).
   */
  kill(): void;
  /** Subscribe to raw stdout lines. Returns an unsubscribe function. */
  onLine(cb: (line: string) => void): () => void;
  /** Subscribe to stderr lines (diagnostics only, never protocol). */
  onStderr(cb: (line: string) => void): () => void;
  /**
   * Subscribe to process exit. Fires exactly once. `code` is the exit
   * code, or null when it cannot be determined (e.g. killed by signal).
   */
  onExit(cb: (code: number | null) => void): () => void;
}

/**
 * Placeholder port for environments where no spawn bridge exists.
 * `start()` fails explicitly with ENGINE_UNAVAILABLE; the session maps
 * that to the worker-not-responding recovery surface, so the shell
 * degrades honestly instead of pretending a mock engine is real.
 */
export class UnsupportedSidecarPort implements SidecarPort {
  async start(): Promise<void> {
    throw new SidecarError(
      ERR.ENGINE_UNAVAILABLE,
      "engine sidecar spawn is not wired into the Tauri shell yet " +
        "(requires a process bridge; see src/sidecar/README.md)",
    );
  }
  writeLine(): void {
    throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "sidecar port is unavailable");
  }
  closeStdin(): void {
    /* no worker */
  }
  kill(): void {
    /* no worker */
  }
  onLine(): () => void {
    return () => undefined;
  }
  onStderr(): () => void {
    return () => undefined;
  }
  onExit(): () => void {
    return () => undefined;
  }
}

/**
 * The port used when no explicit one is injected:
 * - inside the Tauri webview: {@link TauriSidecarPort} (ENG-002 — the
 *   Rust engine supervisor spawns `python -m hornscribe.worker`);
 * - in a plain browser (`vite dev`): {@link DevBridgeSidecarPort} (#86) —
 *   it spawns the real worker through the devEngineBridge Vite middleware
 *   when the bridge is reachable, and silently degrades to the
 *   in-process MockSidecarPort NDJSON emulation when it is
 *   not, so the transcription UX stays exercisable without Python.
 */
export function createDefaultSidecarPort(): SidecarPort {
  if (isTauriRuntime()) return new TauriSidecarPort();
  return new DevBridgeSidecarPort();
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import { devEngineBridge } from "./scripts/devEngineBridge.mjs";

// Tauri dev server convention: fixed port 1420.
// The webview loads this devUrl in dev mode; in production it serves
// the bundled `dist/` directory through the tauri:// custom protocol.
export default defineConfig({
  plugins: [react(), devEngineBridge()],
  clearScreen: false,
  server: {
    port: 1420,
    strictPort: true,
    watch: {
      // Rust sources are not part of the frontend build.
      ignored: ["**/src-tauri/**"],
    },
  },
  build: {
    outDir: "dist",
    // Tauri serves dist via a custom protocol; relative base keeps it portable.
    target: "es2022",
    sourcemap: false,
  },
});
